class IndependentSpyAaplStrategies(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.WILDERS
        )

        self.previous_closes = {}
        self.aapl_red_streak = 0
        self.previous_spy_signal = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        # Include enough pre-start daily observations to fully form every
        # indicator and retain a prior fully formed SPY close/SMA pair.
        self.set_warm_up(self.SMA_PERIOD + 1, Resolution.DAILY)

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if symbol in data.bars:
                bars[ticker] = data.bars[symbol]

        # Market-state quantities continue to advance for every ticker whose
        # bar is available, even when another ticker is absent.
        if "SPY" in bars:
            spy_close = float(bars["SPY"].close)
            self.spy_sma.update(self.time, spy_close)
        else:
            spy_close = None

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].close)
            previous_aapl_close = self.previous_closes.get("AAPL")
            if previous_aapl_close is None or aapl_close >= previous_aapl_close:
                self.aapl_red_streak = 0
            else:
                self.aapl_red_streak += 1
            self.aapl_rsi.update(self.time, aapl_close)
        else:
            aapl_close = None

        for ticker, bar in bars.items():
            self.previous_closes[ticker] = float(bar.close)

        all_bars_present = len(bars) == len(self.symbols)
        indicators_ready = self.spy_sma.is_ready and self.aapl_rsi.is_ready

        current_spy_signal = None
        if spy_close is not None and self.spy_sma.is_ready:
            current_spy_signal = (spy_close, float(self.spy_sma.current.value))

        if (
            self.is_warming_up
            or not all_bars_present
            or not indicators_ready
            or self.previous_spy_signal is None
        ):
            if current_spy_signal is not None:
                self.previous_spy_signal = current_spy_signal
            return

        previous_spy_close, previous_spy_sma = self.previous_spy_signal
        current_spy_close, current_spy_sma = current_spy_signal

        spy_crossed_above = (
            previous_spy_close <= previous_spy_sma
            and current_spy_close > current_spy_sma
        )
        spy_crossed_below = (
            previous_spy_close >= previous_spy_sma
            and current_spy_close < current_spy_sma
        )

        # Evaluate every sell before either independent strategy's buy.
        if self.strategy_a_shares > 0 and spy_crossed_below:
            self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.current.value > 60:
            self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crossed_above:
            shares = floor(0.40 * float(self.portfolio.total_portfolio_value) / spy_close)
            if shares > 0:
                self.market_order(self.symbols["SPY"], shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            cash = float(self.portfolio.cash_book["USD"].amount)
            if cash >= 20_000:
                shares = floor(20_000 / aapl_close)
                if shares > 0:
                    self.market_order(self.symbols["AAPL"], shares)
                    self.strategy_b_shares = shares

        self.previous_spy_signal = current_spy_signal

