class IndependentSpyAaplStrategies(QCAlgorithm):
    SMA_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=self.SMA_PERIOD)
        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_id = None
        self.aapl_order_id = None

    def OnData(self, data):
        bars = data.Bars
        all_present = all(bars.ContainsKey(symbol) for symbol in self.symbols.values())

        spy_bar = bars[self.symbols["SPY"]] if bars.ContainsKey(self.symbols["SPY"]) else None
        aapl_bar = bars[self.symbols["AAPL"]] if bars.ContainsKey(self.symbols["AAPL"]) else None

        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma

        if spy_bar is not None:
            spy_close = spy_bar.Close
            self.spy_closes.append(spy_close)
            current_spy_sma = None
            if len(self.spy_closes) == self.SMA_PERIOD:
                current_spy_sma = sum(self.spy_closes) / self.SMA_PERIOD
            self.previous_spy_close = spy_close
            self.previous_spy_sma = current_spy_sma
        else:
            spy_close = None
            current_spy_sma = None

        if aapl_bar is not None:
            aapl_close = aapl_bar.Close
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)
        else:
            aapl_close = None

        if not all_present:
            return

        if (
            previous_spy_close is None
            or previous_spy_sma is None
            or current_spy_sma is None
            or not self.aapl_rsi.IsReady
        ):
            return

        spy_crossed_below = (
            previous_spy_close >= previous_spy_sma
            and spy_close < current_spy_sma
        )
        spy_crossed_above = (
            previous_spy_close <= previous_spy_sma
            and spy_close > current_spy_sma
        )

        # All independent strategies evaluate their sell before their buy.
        if self.spy_lot > 0 and self.spy_order_id is None and spy_crossed_below:
            ticket = self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
            self.spy_order_id = ticket.OrderId
        elif self.spy_lot == 0 and self.spy_order_id is None and spy_crossed_above:
            quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                ticket = self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_order_id = ticket.OrderId

        if (
            self.aapl_lot > 0
            and self.aapl_order_id is None
            and self.aapl_rsi.Current.Value > 60
        ):
            ticket = self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_order_id = ticket.OrderId
        elif (
            self.aapl_lot == 0
            and self.aapl_order_id is None
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20_000
        ):
            quantity = floor(20_000 / aapl_close)
            if quantity > 0:
                ticket = self.MarketOrder(self.symbols["AAPL"], quantity)
                self.aapl_order_id = ticket.OrderId

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled or order_event.Status == OrderStatus.PartiallyFilled:
            if order_event.Symbol == self.symbols["SPY"]:
                self.spy_lot += int(order_event.FillQuantity)
            elif order_event.Symbol == self.symbols["AAPL"]:
                self.aapl_lot += int(order_event.FillQuantity)

        if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            if order_event.OrderId == self.spy_order_id:
                self.spy_order_id = None
            elif order_event.OrderId == self.aapl_order_id:
                self.aapl_order_id = None

