            self.RSI_PERIOD, MovingAverageType.Wilders
        )
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        # Each strategy owns and accounts for only its own lot.
        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        # Market-state quantities continue to consume every available ticker bar,
        # even on a day when another subscription is missing.
        if data.Bars.ContainsKey(spy):
            self.spy_closes.Add(float(data.Bars[spy].Close))

        if data.Bars.ContainsKey(aapl):
            aapl_bar = data.Bars[aapl]
            aapl_close = float(aapl_bar.Close)
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        # A missing bar for any subscription suppresses every rule for the day.
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        spy_bar = data.Bars[spy]
        aapl_bar = data.Bars[aapl]

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and self.spy_closes.IsReady:
            current_sma = sum(self.spy_closes[i] for i in range(self.SMA_PERIOD)) / self.SMA_PERIOD
            previous_sma = sum(
                self.spy_closes[i] for i in range(1, self.SMA_PERIOD + 1)
            ) / self.SMA_PERIOD
            crossed_below = (
                self.spy_closes[1] >= previous_sma
                and self.spy_closes[0] < current_sma
            )
            if crossed_below:
                self.MarketOrder(spy, -self.spy_lot)
