        if self.strategy_b_shares > 0:
            if self.aapl_rsi.is_ready and float(self.aapl_rsi.current.value) > 60:
                self.market_order(
                    self.symbols["AAPL"], -self.strategy_b_shares
                )
                self.strategy_b_shares = 0
        elif len(self.aapl_closes) == 4:
