class ParallelSpyAaplStrategies(QCAlgorithm):
    """Two independent daily strategies with separately accounted lots."""

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.sma_period = 20
        self.spy_closes = deque(maxlen=self.sma_period + 1)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.WILDERS
        )

        # These quantities belong only to their named strategy.
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        # Market-state quantities continue to update even when another symbol's
        # bar is absent and trading evaluation must be skipped.
        if spy in data.bars:
            self.spy_closes.append(float(data.bars[spy].close))

        if aapl in data.bars:
            aapl_bar = data.bars[aapl]
            aapl_close = float(aapl_bar.close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        if any(symbol not in data.bars for symbol in self.symbols.values()):
            return

        spy_close = float(data.bars[spy].close)
        aapl_close = float(data.bars[aapl].close)

        # Sells are evaluated before buys on every complete daily slice.
        if self.strategy_a_shares > 0 and self._spy_crosses_below_sma():
            self.market_order(spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.is_ready:
            if float(self.aapl_rsi.current.value) > 60:
                self.market_order(aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and self._spy_crosses_above_sma():
            target_value = 0.40 * float(self.portfolio.total_portfolio_value)
            quantity = floor(target_value / spy_close)
            if quantity > 0:
                self.market_order(spy, quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_rsi.is_ready:
            if self.aapl_red_streak >= 3 and float(self.portfolio.cash) >= 20_000:
                quantity = floor(20_000 / aapl_close)
                if quantity > 0:
                    self.market_order(aapl, quantity)
                    self.strategy_b_shares = quantity

    def _spy_crosses_above_sma(self):
        if len(self.spy_closes) < self.sma_period + 1:
            return False
        values = list(self.spy_closes)
        yesterday_close = values[-2]
        today_close = values[-1]
        yesterday_sma = sum(values[-self.sma_period - 1:-1]) / self.sma_period
        today_sma = sum(values[-self.sma_period:]) / self.sma_period
        return yesterday_close <= yesterday_sma and today_close > today_sma

    def _spy_crosses_below_sma(self):
        if len(self.spy_closes) < self.sma_period + 1:
            return False
        values = list(self.spy_closes)
        yesterday_close = values[-2]
        today_close = values[-1]
        yesterday_sma = sum(values[-self.sma_period - 1:-1]) / self.sma_period
        today_sma = sum(values[-self.sma_period:]) / self.sma_period
        return yesterday_close >= yesterday_sma and today_close < today_sma

