class IndependentSpyAaplStrategies(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy_closes = RollingWindow[float](self.SMA_PERIOD + 1)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.WILDERS
        )

        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0

    def on_data(self, data: Slice):
        bars = data.bars

        spy_bar = bars.get(self.symbols["SPY"])
        if spy_bar is not None:
            self.spy_closes.add(float(spy_bar.close))

        aapl_bar = bars.get(self.symbols["AAPL"])
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_close)

        if any(bars.get(symbol) is None for symbol in self.symbols.values()):
            return

        self._evaluate_strategy_a(float(spy_bar.close))
        self._evaluate_strategy_b(float(aapl_bar.close))

    def _evaluate_strategy_a(self, spy_close):
        if not self.spy_closes.is_ready:
            return

        sma_today = sum(self.spy_closes[i] for i in range(self.SMA_PERIOD)) / self.SMA_PERIOD
        sma_yesterday = (
            sum(self.spy_closes[i] for i in range(1, self.SMA_PERIOD + 1))
            / self.SMA_PERIOD
        )
        yesterday_close = self.spy_closes[1]

        crosses_below = yesterday_close >= sma_yesterday and spy_close < sma_today
        crosses_above = yesterday_close <= sma_yesterday and spy_close > sma_today

        if self.strategy_a_quantity > 0:
            if crosses_below:
                self.market_order(self.symbols["SPY"], -self.strategy_a_quantity)
                self.strategy_a_quantity = 0
        elif crosses_above:
            quantity = int(
                (self.portfolio.total_portfolio_value * 0.40) // spy_close
            )
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.strategy_a_quantity = quantity

    def _evaluate_strategy_b(self, aapl_close):
        if not self.aapl_rsi.is_ready:
            return

        if self.strategy_b_quantity > 0:
            if self.aapl_rsi.current.value > 60:
                self.market_order(self.symbols["AAPL"], -self.strategy_b_quantity)
                self.strategy_b_quantity = 0
        elif self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
            quantity = int(20_000 // aapl_close)
            if quantity > 0:
                self.market_order(self.symbols["AAPL"], quantity)
                self.strategy_b_quantity = quantity

