        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                return
            bars[ticker] = data.Bars[symbol]

        # LEAN adjusts security holdings for corporate actions; mirror those
        # adjustments in each strategy's private share count.
        if self.spy_lot > 0:
            self.spy_lot = int(self.Portfolio[self.symbols["SPY"]].Quantity)
        if self.aapl_lot > 0:
