class ParallelSpyAaplStrategies(QCAlgorithm):
    """Two independent daily strategies with separately tracked lots."""

    SMA_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        # Keep one extra observation so both sides of an SMA cross are fully
        # formed. The current SMA always includes the current close.
        self.spy_closes = deque(maxlen=self.SMA_PERIOD + 1)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        # These quantities are private strategy lots, not aggregate holdings.
        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                bars[ticker] = None
            else:
                bars[ticker] = data.Bars[symbol]

        # Market-state quantities advance whenever their own ticker has data,
        # even on a day on which another ticker is absent.
        spy_bar = bars["SPY"]
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.Close))

        aapl_bar = bars["AAPL"]
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        # A missing daily bar for any subscription suppresses every rule.
        if any(bar is None for bar in bars.values()):
            return

        # Every rule waits until all state it can use is fully formed. An extra
        # SPY close is required to compare yesterday's fully formed SMA.
        if len(self.spy_closes) < self.SMA_PERIOD + 1 or not self.aapl_rsi.IsReady:
            return

        spy_values = list(self.spy_closes)
        previous_spy_close = spy_values[-2]
        current_spy_close = spy_values[-1]
        previous_spy_sma = sum(spy_values[:-1]) / self.SMA_PERIOD
        current_spy_sma = sum(spy_values[1:]) / self.SMA_PERIOD

        # Sells are evaluated before buys. Each strategy can evaluate only the
        # side appropriate to its own lot state.
        if self.spy_lot > 0:
            if previous_spy_close >= previous_spy_sma and current_spy_close < current_spy_sma:
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
        elif previous_spy_close <= previous_spy_sma and current_spy_close > current_spy_sma:
            quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if self.aapl_lot > 0:
            if float(self.aapl_rsi.Current.Value) > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
        elif self.aapl_red_streak >= 3:
            available_cash = float(self.Portfolio.CashBook["USD"].Amount)
            if available_cash >= 20_000:
                quantity = floor(20_000 / float(aapl_bar.Close))
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

