    RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in tickers
        }

        self.spy_closes = deque(maxlen=self.SMA_PERIOD)
        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.WILDERS
        )
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        spy_close = None
        spy_sma = None
        if "SPY" in bars:
            spy_close = bars["SPY"].close
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == self.SMA_PERIOD:
                spy_sma = sum(self.spy_closes) / self.SMA_PERIOD

        aapl_close = None
        if "AAPL" in bars:
            aapl_close = bars["AAPL"].close
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.update(bars["AAPL"].end_time, aapl_close)

        all_bars_present = len(bars) == len(self.symbols)
        if all_bars_present:
            self._evaluate_spy(spy_close, spy_sma)
            self._evaluate_aapl(aapl_close)

        if "SPY" in bars:
            self.previous_spy_close = spy_close
            self.previous_spy_sma = spy_sma
        if "AAPL" in bars:
            self.previous_aapl_close = aapl_close

    def _evaluate_spy(self, close, sma):
        if sma is None or self.previous_spy_sma is None:
            return

        crosses_below = (
            self.previous_spy_close >= self.previous_spy_sma
            and close < sma
        )
        crosses_above = (
            self.previous_spy_close <= self.previous_spy_sma
            and close > sma
        )

        if self.spy_lot > 0:
            if crosses_below:
                self.market_order(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
        elif crosses_above:
            quantity = floor(0.40 * self.portfolio.total_portfolio_value / close)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

    def _evaluate_aapl(self, close):
        if not self.aapl_rsi.is_ready:
            return

        if self.aapl_lot > 0:
            if self.aapl_rsi.current.value > 60:
                self.market_order(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
        elif self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
            quantity = floor(20_000 / close)
            if quantity > 0:
                self.market_order(self.symbols["AAPL"], quantity)
                self.aapl_lot = quantity

