class IndependentSpyAaplStrategies(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=self.SMA_PERIOD + 1)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.Wilders
        )

        # These quantities are the private lots owned by the two strategies.
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        spy_symbol = self.symbols["SPY"]
        aapl_symbol = self.symbols["AAPL"]
        spy_bar = data.Bars[spy_symbol] if spy_symbol in data.Bars else None
        aapl_bar = data.Bars[aapl_symbol] if aapl_symbol in data.Bars else None

        # Market-state quantities continue to consume every available bar.
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.Close))
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)

        # The system is evaluated only when all five daily bars are present.
        if any(symbol not in data.Bars for symbol in self.symbols.values()):
            return

        spy_close = float(spy_bar.Close)
        aapl_close = float(aapl_bar.Close)

        # Sells are evaluated before buys.
        self._evaluate_strategy_a_sell()
        self._evaluate_strategy_b_sell()
        self._evaluate_strategy_a_buy(spy_close)
        self._evaluate_strategy_b_buy(aapl_close)

    def _spy_cross(self):
        if len(self.spy_closes) < self.SMA_PERIOD + 1:
            return None

        closes = list(self.spy_closes)
        yesterday_close = closes[-2]
        today_close = closes[-1]
        yesterday_sma = sum(closes[:-1]) / self.SMA_PERIOD
        today_sma = sum(closes[1:]) / self.SMA_PERIOD

        crosses_above = yesterday_close <= yesterday_sma and today_close > today_sma
        crosses_below = yesterday_close >= yesterday_sma and today_close < today_sma
        return crosses_above, crosses_below

    def _evaluate_strategy_a_sell(self):
        if self.strategy_a_shares == 0:
            return
        cross = self._spy_cross()
        if cross is not None and cross[1]:
            self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
            self.strategy_a_shares = 0

    def _evaluate_strategy_b_sell(self):
        if self.strategy_b_shares == 0 or not self.aapl_rsi.IsReady:
            return
        if float(self.aapl_rsi.Current.Value) > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

    def _evaluate_strategy_a_buy(self, close):
        if self.strategy_a_shares != 0:
            return
        cross = self._spy_cross()
        if cross is not None and cross[0]:
            shares = floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / close)
            if shares > 0:
                self.MarketOrder(self.symbols["SPY"], shares)
                self.strategy_a_shares = shares

    def _evaluate_strategy_b_buy(self, close):
        if self.strategy_b_shares != 0 or not self.aapl_rsi.IsReady:
            return
