class IndependentSpyAaplStrategies(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = self.sma(self.spy, self.SMA_PERIOD, Resolution.DAILY)
        self.aapl_rsi = self.rsi(
            self.aapl,
            self.RSI_PERIOD,
            MovingAverageType.WILDERS,
            Resolution.DAILY,
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False

    def on_data(self, data: Slice):
        spy_bar = data.bars.get(self.spy)
        aapl_bar = data.bars.get(self.aapl)

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_bar.close

        spy_sma_value = self.spy_sma.current.value if self.spy_sma.is_ready else None
        prior_spy_close = self.previous_spy_close
        prior_spy_sma = self.previous_spy_sma
        if spy_bar is not None:
            self.previous_spy_close = spy_bar.close
            self.previous_spy_sma = spy_sma_value

        if any(data.bars.get(symbol) is None for symbol in self.symbols.values()):
            return
        if (
            not self.spy_sma.is_ready
            or not self.aapl_rsi.is_ready
            or prior_spy_close is None
            or prior_spy_sma is None
        ):
            return

        spy_crossed_below = (
            prior_spy_close >= prior_spy_sma
            and spy_bar.close < spy_sma_value
        )
        if self.spy_lot > 0 and not self.spy_order_pending and spy_crossed_below:
            self.spy_order_pending = True
            self.market_order(self.spy, -self.spy_lot, tag="Strategy A sell")

        if (
            self.aapl_lot > 0
            and not self.aapl_order_pending
            and self.aapl_rsi.current.value > 60
        ):
            self.aapl_order_pending = True
            self.market_order(self.aapl, -self.aapl_lot, tag="Strategy B sell")

        spy_crossed_above = (
            prior_spy_close <= prior_spy_sma
            and spy_bar.close > spy_sma_value
        )
        if self.spy_lot == 0 and not self.spy_order_pending and spy_crossed_above:
            quantity = self.calculate_order_quantity(self.spy, 0.40)
            if quantity > 0:
                self.spy_order_pending = True
                self.market_order(self.spy, quantity, tag="Strategy A buy")

        if (
            self.aapl_lot == 0
            and not self.aapl_order_pending
            and self.aapl_red_streak >= 3
            and self.portfolio.cash >= 20_000
        ):
            quantity = int(20_000 // aapl_bar.close)
            if quantity > 0:
                self.aapl_order_pending = True
                self.market_order(self.aapl, quantity, tag="Strategy B buy")

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status not in (OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID):
            return

        if order_event.symbol == self.spy:
            if order_event.status == OrderStatus.FILLED:
                self.spy_lot += order_event.fill_quantity
            self.spy_order_pending = False
        elif order_event.symbol == self.aapl:
            if order_event.status == OrderStatus.FILLED:
                self.aapl_lot += order_event.fill_quantity
            self.aapl_order_pending = False

