class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent, close-of-day strategies with separately tracked lots."""

    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_closes = deque(maxlen=self.SMA_PERIOD)
        self.previous_spy_above_sma = None
        self.previous_closes = {}
        self.aapl_red_streak = 0

        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.WILDERS
        )

        # These quantities are private strategy-lot ledgers, rather than the
        # aggregate security holdings maintained by LEAN.
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        # Market-state quantities advance whenever their own ticker has data,
        # even on a day on which another subscription is missing.
        spy_ready_before_update = len(self.spy_closes) == self.SMA_PERIOD
        if "SPY" in bars:
            spy_close = float(bars["SPY"].close)
            self.spy_closes.append(spy_close)
            spy_ready = len(self.spy_closes) == self.SMA_PERIOD
            spy_above_sma = (
                spy_close > sum(self.spy_closes) / self.SMA_PERIOD
                if spy_ready
                else None
            )
        else:
            spy_ready = False
            spy_above_sma = None

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            aapl_close = float(aapl_bar.close)
            previous_aapl_close = self.previous_closes.get("AAPL")
            if previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi.update(aapl_bar.end_time, aapl_close)

        have_every_bar = len(bars) == len(self.symbols)
        if have_every_bar:
            # Sells are evaluated before buys. The two lots otherwise operate
            # independently and may both act on the same bar.
            spy_crossed_below = (
                spy_ready_before_update
                and self.previous_spy_above_sma is True
                and spy_above_sma is False
            )
            if self.strategy_a_shares > 0 and spy_crossed_below:
                self.market_order(
                    self.symbols["SPY"], -self.strategy_a_shares,
                    tag="Strategy A: close crossed below SMA"
                )
                self.strategy_a_shares = 0

            if (
                self.strategy_b_shares > 0
                and self.aapl_rsi.is_ready
                and self.aapl_rsi.current.value > 60
            ):
                self.market_order(
                    self.symbols["AAPL"], -self.strategy_b_shares,
                    tag="Strategy B: RSI closed above 60"
                )
                self.strategy_b_shares = 0

            spy_crossed_above = (
                spy_ready_before_update
                and self.previous_spy_above_sma is False
                and spy_above_sma is True
            )
            if self.strategy_a_shares == 0 and spy_crossed_above:
                quantity = floor(
                    0.40 * float(self.portfolio.total_portfolio_value)
                    / float(bars["SPY"].close)
                )
                if quantity > 0:
                    self.market_order(
                        self.symbols["SPY"], quantity,
                        tag="Strategy A: close crossed above SMA"
                    )
                    self.strategy_a_shares = quantity

            if (
                self.strategy_b_shares == 0
                and self.aapl_rsi.is_ready
                and self.aapl_red_streak >= 3
                and float(self.portfolio.cash) >= 20_000
            ):
                quantity = floor(20_000 / float(bars["AAPL"].close))
                if quantity > 0:
                    self.market_order(
                        self.symbols["AAPL"], quantity,
                        tag="Strategy B: three consecutive red days"
                    )
                    self.strategy_b_shares = quantity

        if "SPY" in bars and spy_ready:
            self.previous_spy_above_sma = spy_above_sma

        for ticker, bar in bars.items():
            self.previous_closes[ticker] = float(bar.close)

