class IndependentSpyAaplStrategies(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.WILDERS
        )

        self.spy_previous_close = None
        self.spy_previous_sma = None
        self.aapl_closes = deque(maxlen=4)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        bars = {}
        all_bars_present = True
        for ticker, symbol in self.symbols.items():
            if not data.bars.contains_key(symbol):
                all_bars_present = False
                continue
            bar = data.bars[symbol]
            if bar is None:
                all_bars_present = False
                continue
            bars[ticker] = bar

        spy_bar = bars.get("SPY")
        if spy_bar is not None:
            spy_close = spy_bar.close
            self.spy_sma.update(data.time, spy_close)

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            aapl_close = aapl_bar.close
            self.aapl_rsi.update(data.time, aapl_close)
            self.aapl_closes.append(aapl_close)

        if all_bars_present:
            self._evaluate_strategy_a(spy_bar.close)
            self._evaluate_strategy_b(aapl_bar.close)

        if spy_bar is not None and self.spy_sma.is_ready:
            self.spy_previous_close = spy_bar.close
            self.spy_previous_sma = self.spy_sma.current.value

    def _evaluate_strategy_a(self, close):
        if (
            not self.spy_sma.is_ready
            or self.spy_previous_close is None
            or self.spy_previous_sma is None
        ):
            return

        sma = self.spy_sma.current.value

        if self.strategy_a_shares > 0:
            crossed_below = (
                self.spy_previous_close >= self.spy_previous_sma
                and close < sma
            )
            if crossed_below:
                self.market_order(
                    self.symbols["SPY"], -self.strategy_a_shares
                )
                self.strategy_a_shares = 0

        if self.strategy_a_shares == 0:
            crossed_above = (
                self.spy_previous_close <= self.spy_previous_sma
                and close > sma
            )
            if crossed_above:
                shares = floor(
                    self.portfolio.total_portfolio_value * 0.40 / close
                )
                if shares > 0:
                    self.market_order(self.symbols["SPY"], shares)
                    self.strategy_a_shares = shares

    def _evaluate_strategy_b(self, close):
        if not self.aapl_rsi.is_ready or len(self.aapl_closes) < 4:
            return

        if self.strategy_b_shares > 0:
            if self.aapl_rsi.current.value > 60:
                self.market_order(
                    self.symbols["AAPL"], -self.strategy_b_shares
                )
                self.strategy_b_shares = 0

        if self.strategy_b_shares == 0:
            closes = list(self.aapl_closes)
            red_for_three_days = (
                closes[-3] < closes[-4]
                and closes[-2] < closes[-3]
                and closes[-1] < closes[-2]
            )
            if red_for_three_days and self.portfolio.cash >= 20_000:
                shares = floor(20_000 / close)
                if shares > 0:
                    self.market_order(self.symbols["AAPL"], shares)
                    self.strategy_b_shares = shares

