class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=21)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        # Market-state quantities keep advancing even when another ticker is
        # missing and the day's trading rules consequently cannot be run.
        if data.Bars.ContainsKey(spy):
            self.spy_closes.append(float(data.Bars[spy].Close))

        if data.Bars.ContainsKey(aapl):
            aapl_close = float(data.Bars[aapl].Close)
            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(data.Bars[aapl].EndTime, aapl_close)

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if len(self.spy_closes) < 21 or not self.aapl_rsi.IsReady:
            return

        spy_close = self.spy_closes[-1]
        spy_previous_close = self.spy_closes[-2]
        spy_sma = sum(list(self.spy_closes)[-20:]) / 20.0
        spy_previous_sma = sum(list(self.spy_closes)[:20]) / 20.0
        spy_crossed_above = spy_previous_close <= spy_previous_sma and spy_close > spy_sma
        spy_crossed_below = spy_previous_close >= spy_previous_sma and spy_close < spy_sma

        # Evaluate every sell before either independent strategy's buy.
        if self.Portfolio[spy].Quantity != 0 and spy_crossed_below:
            self.MarketOrder(spy, -self.Portfolio[spy].Quantity)

        if self.Portfolio[aapl].Quantity != 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(aapl, -self.Portfolio[aapl].Quantity)

        if self.Portfolio[spy].Quantity == 0 and spy_crossed_above:
            quantity = floor(0.40 * self.Portfolio.TotalPortfolioValue / spy_close)
            if quantity > 0:
                self.MarketOrder(spy, quantity)

        if self.Portfolio[aapl].Quantity == 0 and self.aapl_red_streak >= 3:
            cash_amount = 20_000
            if self.Portfolio.Cash >= cash_amount:
                quantity = floor(cash_amount / float(data.Bars[aapl].Close))
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)

