class IndependentSpyAaplStrategies(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=self.SMA_PERIOD)
        self.previous_spy_relation = None

        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.Wilders
        )
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot_open = False
        self.aapl_lot_shares = 0

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            spy_close = data.Bars[spy].Close
            self.spy_closes.append(spy_close)

        if data.Bars.ContainsKey(aapl):
            aapl_bar = data.Bars[aapl]
            aapl_close = aapl_bar.Close
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)

        all_bars_present = all(
            data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )
        if not all_bars_present:
            self._update_spy_relation_if_ready()
            return

        # Sells are evaluated before buys.
        spy_crossed_below, spy_crossed_above = self._spy_crosses()

        if self.spy_lot_open and spy_crossed_below:
            self.Liquidate(spy)
            self.spy_lot_open = False

        if self.aapl_lot_shares > 0 and self.aapl_rsi.IsReady:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(aapl, -self.aapl_lot_shares)
                self.aapl_lot_shares = 0

        if not self.spy_lot_open and spy_crossed_above:
            quantity = self.CalculateOrderQuantity(spy, 0.40)
            if quantity > 0:
                self.MarketOrder(spy, quantity)
                self.spy_lot_open = True

        if (
            self.aapl_lot_shares == 0
            and self.aapl_rsi.IsReady
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20_000
        ):
            quantity = floor(20_000 / data.Bars[aapl].Close)
            if quantity > 0:
                self.MarketOrder(aapl, quantity)
                self.aapl_lot_shares = quantity

        self._update_spy_relation_if_ready()

    def _spy_crosses(self):
        if len(self.spy_closes) < self.SMA_PERIOD:
            return False, False

        close = self.spy_closes[-1]
        average = sum(self.spy_closes) / self.SMA_PERIOD
        relation = close - average
        if self.previous_spy_relation is None:
            return False, False

        crossed_below = self.previous_spy_relation >= 0 and relation < 0
        crossed_above = self.previous_spy_relation <= 0 and relation > 0
        return crossed_below, crossed_above

    def _update_spy_relation_if_ready(self):
        if len(self.spy_closes) == self.SMA_PERIOD:
            close = self.spy_closes[-1]
            average = sum(self.spy_closes) / self.SMA_PERIOD
            self.previous_spy_relation = close - average

