            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)

        have_all_bars = len(bars) == len(self.symbols)
        all_history_ready = (
            spy_difference is not None
            and self.spy_previous_difference is not None
            and self.aapl_rsi.IsReady
            and self.aapl_previous_close is not None
        )

        if have_all_bars and all_history_ready:
            spy_crossed_below = (
                self.spy_previous_difference >= 0 and spy_difference < 0
            )
            if self.spy_lot_open and spy_crossed_below:
                quantity = int(self.Portfolio[self.symbols["SPY"]].Quantity)
