class ParallelSpyAaplStrategies(QCAlgorithm):
    SMA_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]
        self.spy_sma = self.SMA(self.spy, self.SMA_PERIOD, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.spy_previous_close = None
        self.spy_previous_sma = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.pending_orders = {}
        self.spy_pending = False
        self.aapl_pending = False

        self.SetWarmUp(max(self.SMA_PERIOD, 15), Resolution.Daily)

    def OnData(self, data):
        spy_bar = data.Bars[self.spy] if self.spy in data.Bars else None
        aapl_bar = data.Bars[self.aapl] if self.aapl in data.Bars else None

        if aapl_bar is not None:
            if self.aapl_previous_close is not None:
                if aapl_bar.Close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_bar.Close

        previous_spy_close = self.spy_previous_close
        previous_spy_sma = self.spy_previous_sma
        if spy_bar is not None and self.spy_sma.IsReady:
            self.spy_previous_close = spy_bar.Close
            self.spy_previous_sma = self.spy_sma.Current.Value

        bars = data.Bars
        if any(symbol not in bars for symbol in self.symbols.values()):
            return
        if self.IsWarmingUp or not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = spy_bar.Close
        spy_sma = self.spy_sma.Current.Value

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and not self.spy_pending:
            if (
                previous_spy_close is not None
                and previous_spy_sma is not None
                and previous_spy_close >= previous_spy_sma
                and spy_close < spy_sma
            ):
                self._submit_lot_order(self.spy, -self.spy_lot, "spy")

        if self.aapl_lot > 0 and not self.aapl_pending:
            if self.aapl_rsi.Current.Value > 60:
                self._submit_lot_order(self.aapl, -self.aapl_lot, "aapl")

        if self.spy_lot == 0 and not self.spy_pending:
            if (
                previous_spy_close is not None
                and previous_spy_sma is not None
                and previous_spy_close <= previous_spy_sma
                and spy_close > spy_sma
            ):
                quantity = self.CalculateOrderQuantity(self.spy, 0.40)
                if quantity > 0:
                    self._submit_lot_order(self.spy, quantity, "spy")

        if self.aapl_lot == 0 and not self.aapl_pending:
            if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                quantity = floor(20_000 / aapl_bar.Close)
                if quantity > 0:
                    self._submit_lot_order(self.aapl, quantity, "aapl")

    def _submit_lot_order(self, symbol, quantity, strategy):
        ticket = self.MarketOrder(symbol, quantity)
        self.pending_orders[ticket.OrderId] = strategy
        if strategy == "spy":
            self.spy_pending = True
        else:
            self.aapl_pending = True

    def OnOrderEvent(self, order_event):
        strategy = self.pending_orders.get(order_event.OrderId)
        if strategy is None:
            return

        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            filled = int(order_event.FillQuantity)
            if strategy == "spy":
                self.spy_lot += filled
            else:
                self.aapl_lot += filled

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            del self.pending_orders[order_event.OrderId]
            if strategy == "spy":
                self.spy_pending = False
                self.spy_lot = max(0, self.spy_lot)
            else:
                self.aapl_pending = False
                self.aapl_lot = max(0, self.aapl_lot)

