        aapl_close = data.Bars[aapl].Close

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and old_spy_close >= old_spy_sma and spy_close < self.spy_sma.Current.Value:
            self.MarketOrder(spy, -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(aapl, -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and old_spy_close <= old_spy_sma and spy_close > self.spy_sma.Current.Value:
            quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) // spy_close)
            if quantity > 0:
                self.MarketOrder(spy, quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
            quantity = int(20_000 // aapl_close)
            if quantity > 0:
                self.MarketOrder(aapl, quantity)
                self.aapl_lot = quantity

