class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent, privately accounted daily equity strategies."""

    SPY_SMA_PERIOD = 20
    AAPL_RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy_sma = SimpleMovingAverage(self.SPY_SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            self.AAPL_RSI_PERIOD, MovingAverageType.WILDERS
        )

        self.previous_closes = {}
        self.previous_spy_sma = None
        self.aapl_red_streak = 0

        # Holdings are intentionally tracked per strategy rather than inferred from
        # the aggregate security holding.
        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if not data.bars.contains_key(symbol):
                continue
            bars[ticker] = data.bars[symbol]

        # Market-state quantities advance whenever their own ticker has a bar,
        # even on a slice where the rules must not be evaluated.
        spy_bar = bars.get("SPY")
        aapl_bar = bars.get("AAPL")
        previous_spy_close = self.previous_closes.get("SPY")
        previous_aapl_close = self.previous_closes.get("AAPL")

        if spy_bar is not None:
            self.spy_sma.update(self.time, spy_bar.close)

        if aapl_bar is not None:
            self.aapl_rsi.update(self.time, aapl_bar.close)
            if previous_aapl_close is not None:
                if aapl_bar.close < previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        if (
            len(bars) != len(self.symbols)
            or not self.spy_sma.is_ready
            or not self.aapl_rsi.is_ready
        ):
            for ticker, bar in bars.items():
                self.previous_closes[ticker] = bar.close
            if spy_bar is not None and self.spy_sma.is_ready:
                self.previous_spy_sma = self.spy_sma.current.value
            return

        spy_close = bars["SPY"].close
        aapl_close = bars["AAPL"].close

        # Sells are evaluated before buys. Each reason is evaluated only in the
        # state in which that strategy is allowed to use it.
        if (
            self.spy_lot > 0
            and previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.spy_sma.is_ready
            and previous_spy_close >= self.previous_spy_sma
            and spy_close < self.spy_sma.current.value
        ):
            self.market_order(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if (
            self.aapl_lot > 0
            and self.aapl_rsi.is_ready
            and self.aapl_rsi.current.value > 60
        ):
            self.market_order(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if (
            self.spy_lot == 0
            and previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.spy_sma.is_ready
            and previous_spy_close <= self.previous_spy_sma
            and spy_close > self.spy_sma.current.value
        ):
            target_value = 0.40 * self.portfolio.total_portfolio_value
            quantity = int(target_value / spy_close)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            cash_required = 20_000
            if self.portfolio.cash >= cash_required:
                quantity = int(cash_required / aapl_close)
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

        for ticker, bar in bars.items():
            self.previous_closes[ticker] = bar.close
        if self.spy_sma.is_ready:
            self.previous_spy_sma = self.spy_sma.current.value

