class IndependentSpyAaplStrategies(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG")
        }

        self.spy_closes = deque(maxlen=self.SMA_PERIOD + 1)
        self.aapl_closes = deque(maxlen=2)
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.WILDERS
        )

        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        spy_bar = bars.get("SPY")
        if spy_bar is not None:
            self.spy_closes.append(spy_bar.close)

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            if self.aapl_closes:
                if aapl_bar.close < self.aapl_closes[-1]:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_closes.append(aapl_bar.close)
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        if len(bars) != len(self.symbols):
            return

        self._evaluate_spy(spy_bar)
        self._evaluate_aapl(aapl_bar)

    def _evaluate_spy(self, bar: TradeBar):
        if len(self.spy_closes) < self.SMA_PERIOD + 1:
            return

        closes = list(self.spy_closes)
        previous_close = closes[-2]
        current_close = closes[-1]
        previous_sma = sum(closes[:-1]) / self.SMA_PERIOD
        current_sma = sum(closes[1:]) / self.SMA_PERIOD

        crosses_below = previous_close >= previous_sma and current_close < current_sma
        if self.spy_lot > 0 and crosses_below:
            self.market_order(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        crosses_above = previous_close <= previous_sma and current_close > current_sma
        if self.spy_lot == 0 and crosses_above:
            quantity = self.calculate_order_quantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

    def _evaluate_aapl(self, bar: TradeBar):
        if not self.aapl_rsi.is_ready or len(self.aapl_closes) < 2:
            return

        if self.aapl_lot > 0 and self.aapl_rsi.current.value > 60:
            self.market_order(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            cash_required = 20_000
            if self.portfolio.cash >= cash_required:
                quantity = int(cash_required / bar.close)
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

