            quantity = floor(20_000 / close)
            if quantity > 0:
                self._submit_aapl_order(quantity)

    def _submit_spy_order(self, quantity):
        self.spy_order_pending = True
        self.MarketOrder(self.symbols["SPY"], quantity, False, "Strategy A")

    def _submit_aapl_order(self, quantity):
        self.aapl_order_pending = True
        self.MarketOrder(self.symbols["AAPL"], quantity, False, "Strategy B")

    def OnOrderEvent(self, order_event):
        fill_quantity = int(order_event.FillQuantity)
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if order.Tag == "Strategy A":
            self.spy_lot += fill_quantity
            if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
                self.spy_order_pending = False
                if self.spy_lot < 0:
                    self.spy_lot = 0

        if order.Tag == "Strategy B":
            self.aapl_lot += fill_quantity
            if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
                self.aapl_order_pending = False
                if self.aapl_lot < 0:
                    self.aapl_lot = 0

