class IndependentSpyAaplStrategies(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.pending_strategy = set()
        self.order_strategies = {}

    def OnData(self, data):
        spy_bar = self._bar(data, "SPY")
        aapl_bar = self._bar(data, "AAPL")

        if spy_bar is not None:
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
        if aapl_bar is not None:
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        bars = {ticker: self._bar(data, ticker) for ticker in self.symbols}
        if any(bar is None for bar in bars.values()):
            if spy_bar is not None:
                self._remember_spy(spy_bar.Close)
            if aapl_bar is not None:
                self.previous_aapl_close = aapl_bar.Close
            return

        indicators_ready = self.spy_sma.IsReady and self.aapl_rsi.IsReady
        spy_close = bars["SPY"].Close
        aapl_close = bars["AAPL"].Close
        spy_sma = self.spy_sma.Current.Value

        if indicators_ready:
            # All independent strategy sells are evaluated before any buys.
            if (
                self.spy_lot > 0
                and "SPY" not in self.pending_strategy
                and self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close >= self.previous_spy_sma
                and spy_close < spy_sma
            ):
                self._submit("SPY", -self.spy_lot, "Strategy A sell")

            if (
                self.aapl_lot > 0
                and "AAPL" not in self.pending_strategy
                and self.aapl_rsi.Current.Value > 60
            ):
                self._submit("AAPL", -self.aapl_lot, "Strategy B sell")

            if (
                self.spy_lot == 0
                and "SPY" not in self.pending_strategy
                and self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close <= self.previous_spy_sma
                and spy_close > spy_sma
            ):
                quantity = int(
                    (self.Portfolio.TotalPortfolioValue * 0.40) / spy_close
                )
                if quantity > 0:
                    self._submit("SPY", quantity, "Strategy A buy")

            if (
                self.aapl_lot == 0
                and "AAPL" not in self.pending_strategy
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20_000
            ):
                quantity = int(20_000 // aapl_close)
                if quantity > 0:
                    self._submit("AAPL", quantity, "Strategy B buy")

        self._remember_spy(spy_close)
        self.previous_aapl_close = aapl_close

    def OnOrderEvent(self, order_event):
        strategy = self.order_strategies.get(order_event.OrderId)
        if strategy is None:
            order = self.Transactions.GetOrderById(order_event.OrderId)
            if order is not None and order.Tag.startswith("Strategy A"):
                strategy = "SPY"
            elif order is not None and order.Tag.startswith("Strategy B"):
                strategy = "AAPL"
            else:
                return

        if order_event.FillQuantity != 0:
            if strategy == "SPY":
                self.spy_lot = max(0, self.spy_lot + order_event.FillQuantity)
            else:
                self.aapl_lot = max(0, self.aapl_lot + order_event.FillQuantity)

        if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            self.pending_strategy.discard(strategy)
            self.order_strategies.pop(order_event.OrderId, None)

    def _bar(self, data, ticker):
        symbol = self.symbols[ticker]
        return data.Bars[symbol] if data.Bars.ContainsKey(symbol) else None

    def _remember_spy(self, close):
        self.previous_spy_close = close
        if self.spy_sma.IsReady:
            self.previous_spy_sma = self.spy_sma.Current.Value

    def _submit(self, strategy, quantity, tag):
        self.pending_strategy.add(strategy)
        ticket = self.MarketOrder(self.symbols[strategy], quantity, False, tag)
        self.order_strategies[ticket.OrderId] = strategy

