class IndependentSpyAaplStrategies(QCAlgorithm):
    SMA_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

        self.SetWarmUp(self.SMA_PERIOD + 1, Resolution.Daily)

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        current_spy_close = None
        current_spy_sma = None
        current_aapl_close = None

        if data.Bars.ContainsKey(spy):
            spy_bar = data.Bars[spy]
            current_spy_close = spy_bar.Close
            self.spy_sma.Update(spy_bar.EndTime, current_spy_close)
            if self.spy_sma.IsReady:
                current_spy_sma = self.spy_sma.Current.Value

        if data.Bars.ContainsKey(aapl):
            aapl_bar = data.Bars[aapl]
            current_aapl_close = aapl_bar.Close
            if self.previous_aapl_close is not None:
                if current_aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, current_aapl_close)

        all_bars_present = all(
            data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )

        if not self.IsWarmingUp and all_bars_present:
            self._evaluate_spy(current_spy_close, current_spy_sma)
            self._evaluate_aapl(current_aapl_close)

        if current_spy_close is not None:
            self.previous_spy_close = current_spy_close
            if current_spy_sma is not None:
                self.previous_spy_sma = current_spy_sma
        if current_aapl_close is not None:
            self.previous_aapl_close = current_aapl_close

    def _evaluate_spy(self, close, sma):
        if (
            close is None
            or sma is None
            or self.previous_spy_close is None
            or self.previous_spy_sma is None
        ):
            return

        crossed_below = (
            self.previous_spy_close >= self.previous_spy_sma and close < sma
        )
        crossed_above = (
            self.previous_spy_close <= self.previous_spy_sma and close > sma
        )

        if self.spy_lot > 0:
            if crossed_below:
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
        elif crossed_above:
            quantity = floor(0.40 * self.Portfolio.TotalPortfolioValue / close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

    def _evaluate_aapl(self, close):
        if close is None or not self.aapl_rsi.IsReady:
            return

        if self.aapl_lot > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
        elif self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
            quantity = floor(20_000 / close)
            if quantity > 0:
                self.MarketOrder(self.symbols["AAPL"], quantity)
                self.aapl_lot = quantity

