        self.ibm = self.add_equity("IBM", Resolution.DAILY).symbol
        self.bac = self.add_equity("BAC", Resolution.DAILY).symbol
        self.aig = self.add_equity("AIG", Resolution.DAILY).symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.WILDERS
        )

        self.previous_spy_difference = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0

    def on_data(self, data: Slice):
        bars = {symbol: data.bars.get(symbol) for symbol in self.symbols}

        spy_bar = bars[self.spy]
        if spy_bar is not None:
            self.spy_sma.update(spy_bar.end_time, spy_bar.close)
            if self.spy_sma.is_ready:
                current_spy_difference = spy_bar.close - self.spy_sma.current.value
            else:
                current_spy_difference = None
        else:
            current_spy_difference = None

        aapl_bar = bars[self.aapl]
        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_bar.close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        all_bars_present = all(bar is not None for bar in bars.values())
        all_indicators_ready = self.spy_sma.is_ready and self.aapl_rsi.is_ready

        if all_bars_present and all_indicators_ready:
            self._evaluate_strategy_a(spy_bar, current_spy_difference)
            self._evaluate_strategy_b(aapl_bar)

        if current_spy_difference is not None:
            self.previous_spy_difference = current_spy_difference

    def _evaluate_strategy_a(self, bar, current_difference):
        if self.previous_spy_difference is None or current_difference is None:
            return

        crossed_below = (
            self.previous_spy_difference >= 0 and current_difference < 0
        )
        crossed_above = (
            self.previous_spy_difference <= 0 and current_difference > 0
        )

        if self.strategy_a_quantity > 0:
            if crossed_below:
                self.market_order(self.spy, -self.strategy_a_quantity)
                self.strategy_a_quantity = 0
        elif crossed_above:
            quantity = int(
                (self.portfolio.total_portfolio_value * 0.40) / bar.close
            )
            if quantity > 0:
                self.market_order(self.spy, quantity)
                self.strategy_a_quantity = quantity

    def _evaluate_strategy_b(self, bar):
        if self.strategy_b_quantity > 0:
            if self.aapl_rsi.current.value > 60:
                self.market_order(self.aapl, -self.strategy_b_quantity)
                self.strategy_b_quantity = 0
        elif self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
            quantity = int(20_000 // bar.close)
            if quantity > 0:
                self.market_order(self.aapl, quantity)
                self.strategy_b_quantity = quantity

