        self.spy_previous_close = None
        self.spy_previous_sma = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(self.RSI_PERIOD, MovingAverageType.Wilders)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        bars = {}
        for symbol in self.symbols.values():
            if data.Bars.ContainsKey(symbol):
                bars[symbol] = data.Bars[symbol]

        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        todays_spy_sma = None
        if spy in bars:
            self.closes[spy].append(float(bars[spy].Close))
            if len(self.closes[spy]) == self.SMA_PERIOD:
                todays_spy_sma = sum(self.closes[spy]) / self.SMA_PERIOD

        if aapl in bars:
            aapl_close = float(bars[aapl].Close)
            prior_aapl_close = self.previous_close[aapl]
            if prior_aapl_close is not None and aapl_close < prior_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi.Update(bars[aapl].EndTime, aapl_close)

        for symbol, bar in bars.items():
            if symbol != spy:
                self.closes[symbol].append(float(bar.Close))

        all_bars_present = len(bars) == len(self.symbols)
        if all_bars_present:
            spy_close = float(bars[spy].Close)
            aapl_close = float(bars[aapl].Close)

            if self.strategy_a_shares > 0:
                crosses_below = (
                    self.spy_previous_close is not None
                    and self.spy_previous_sma is not None
                    and todays_spy_sma is not None
