                    if quantity > 0:
                        self.MarketOrder(spy, quantity)
                        self.strategy_a_shares = quantity

            if self.strategy_b_shares == 0 and self.aapl_rsi.IsReady and self.aapl_red_streak >= 3:
                cash_required = 20_000
                if float(self.Portfolio.CashBook["USD"].Amount) >= cash_required:
