        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.Wilders
        )

        self.previous_closes = {}
        self.previous_spy_sma = None
        self.aapl_red_streak = 0

        # Each strategy owns and manages only its own private lot.
        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        # The system is evaluated only on complete five-security daily slices.
        if any(symbol not in data.Bars for symbol in self.symbols.values()):
            return

        bars = {ticker: data.Bars[symbol] for ticker, symbol in self.symbols.items()}
        spy_close = float(bars["SPY"].Close)
        aapl_close = float(bars["AAPL"].Close)

        previous_aapl_close = self.previous_closes.get("AAPL")
        if previous_aapl_close is None:
            self.aapl_red_streak = 0
        elif aapl_close < previous_aapl_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        self.spy_sma.Update(bars["SPY"].EndTime, spy_close)
        self.aapl_rsi.Update(bars["AAPL"].EndTime, aapl_close)

        previous_spy_close = self.previous_closes.get("SPY")
        current_spy_sma = (
            float(self.spy_sma.Current.Value) if self.spy_sma.IsReady else None
        )

        spy_crossed_above = (
            previous_spy_close is not None
            and self.previous_spy_sma is not None
            and current_spy_sma is not None
            and previous_spy_close <= self.previous_spy_sma
            and spy_close > current_spy_sma
        )
        spy_crossed_below = (
            previous_spy_close is not None
            and self.previous_spy_sma is not None
            and current_spy_sma is not None
            and previous_spy_close >= self.previous_spy_sma
            and spy_close < current_spy_sma
        )

        # Strategy A: sells are evaluated before buys.
        if self.spy_lot > 0:
            if spy_crossed_below:
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
        elif spy_crossed_above:
            quantity = int(
                (0.40 * float(self.Portfolio.TotalPortfolioValue)) // spy_close
            )
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        # Strategy B: sells are evaluated before buys.
        if self.aapl_lot > 0:
            if (
                self.aapl_rsi.IsReady
                and float(self.aapl_rsi.Current.Value) > 60.0
            ):
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
        elif (
            previous_aapl_close is not None
            and self.aapl_red_streak >= 3
            and float(self.Portfolio.Cash) >= 20_000.0
        ):
            quantity = int(20_000.0 // aapl_close)
            if quantity > 0:
                self.MarketOrder(self.symbols["AAPL"], quantity)
                self.aapl_lot = quantity

        for ticker, bar in bars.items():
            self.previous_closes[ticker] = float(bar.Close)
        self.previous_spy_sma = current_spy_sma

