class IndependentSpyAaplStrategies(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_closes = deque(maxlen=self.SMA_PERIOD)
        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.WILDERS
        )

        self.spy_lot = 0
        self.aapl_lot = 0
        self.order_strategy = {}

    def on_data(self, data: Slice):
        bars = data.bars
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        # Market-state quantities continue to consume their own ticker's data
        # even when another subscription is missing on this date.
        if bars.contains_key(spy):
            spy_close = float(bars[spy].close)
            self.spy_closes.append(spy_close)
            spy_sma = (
                sum(self.spy_closes) / self.SMA_PERIOD
                if len(self.spy_closes) == self.SMA_PERIOD
                else None
            )
        else:
            spy_close = None
            spy_sma = None

        if bars.contains_key(aapl):
            aapl_close = float(bars[aapl].close)
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.update(data.time, aapl_close)
        else:
            aapl_close = None

        all_bars_present = all(
            bars.contains_key(symbol) for symbol in self.symbols.values()
        )

        if all_bars_present:
            # Sells are evaluated before buys.  Each strategy can act only on
            # its own private lot.
            if self.spy_lot > 0 and self._spy_crosses_below(spy_close, spy_sma):
                self._submit(spy, -self.spy_lot, "spy")

            if (
                self.aapl_lot > 0
                and self.aapl_rsi.is_ready
                and float(self.aapl_rsi.current.value) > 60
            ):
                self._submit(aapl, -self.aapl_lot, "aapl")

            if self.spy_lot == 0 and self._spy_crosses_above(spy_close, spy_sma):
                quantity = floor(
                    0.40 * float(self.portfolio.total_portfolio_value) / spy_close
                )
                if quantity > 0:
                    self._submit(spy, quantity, "spy")

            if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
                cash = float(self.portfolio.cash_book["USD"].amount)
                if cash >= 20_000:
                    quantity = floor(20_000 / aapl_close)
                    if quantity > 0:
                        self._submit(aapl, quantity, "aapl")

        if spy_close is not None:
            self.previous_spy_close = spy_close
            self.previous_spy_sma = spy_sma
        if aapl_close is not None:
            self.previous_aapl_close = aapl_close

    def _spy_crosses_above(self, close, sma):
        return (
            close is not None
            and sma is not None
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close <= self.previous_spy_sma
            and close > sma
        )

    def _spy_crosses_below(self, close, sma):
        return (
            close is not None
            and sma is not None
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close >= self.previous_spy_sma
            and close < sma
        )

    def _submit(self, symbol, quantity, strategy):
        ticket = self.market_order(symbol, quantity)
        self.order_strategy[ticket.order_id] = strategy

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status not in (OrderStatus.PARTIALLY_FILLED, OrderStatus.FILLED):
            return

        strategy = self.order_strategy.get(order_event.order_id)
        if strategy == "spy":
            self.spy_lot += int(order_event.fill_quantity)
            self.spy_lot = max(0, self.spy_lot)
        elif strategy == "aapl":
            self.aapl_lot += int(order_event.fill_quantity)
            self.aapl_lot = max(0, self.aapl_lot)

