class ParallelSpyAaplStrategies(QCAlgorithm):
    """Two independent, privately accounted daily strategies."""

    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        # Raw-price indicators are updated manually only after a complete daily
        # slice, so every rule observes the same close and missing bars pause all
        # rule evaluation.
        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.WILDERS
        )

        self.previous_closes = {}
        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.aapl_red_streak = 0

        # Shares owned by each strategy, independent of aggregate holdings.
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if symbol not in data.bars:
                return
            bars[ticker] = data.bars[symbol]

        spy_close = float(bars["SPY"].close)
        aapl_close = float(bars["AAPL"].close)
        now = self.time

        previous_aapl_close = self.previous_closes.get("AAPL")
        if previous_aapl_close is None:
            self.aapl_red_streak = 0
        elif aapl_close < previous_aapl_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        self.spy_sma.update(now, spy_close)
        self.aapl_rsi.update(now, aapl_close)

        # Sells are evaluated before buys, and each strategy can evaluate only
        # the side appropriate to its private lot.
        if self.strategy_a_shares > 0:
            if (
                self.spy_sma.is_ready
                and self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close >= self.previous_spy_sma
                and spy_close < self.spy_sma.current.value
            ):
                self.market_order(
                    self.symbols["SPY"], -self.strategy_a_shares, tag="Strategy A sell"
                )
                self.strategy_a_shares = 0
        elif (
            self.spy_sma.is_ready
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close <= self.previous_spy_sma
            and spy_close > self.spy_sma.current.value
        ):
            target_value = 0.40 * float(self.portfolio.total_portfolio_value)
            quantity = int(target_value / spy_close)
            if quantity > 0:
                self.market_order(
                    self.symbols["SPY"], quantity, tag="Strategy A buy"
                )
                self.strategy_a_shares = quantity

        if self.strategy_b_shares > 0:
            if self.aapl_rsi.is_ready and self.aapl_rsi.current.value > 60:
                self.market_order(
                    self.symbols["AAPL"],
                    -self.strategy_b_shares,
                    tag="Strategy B sell",
                )
                self.strategy_b_shares = 0
        elif self.aapl_rsi.is_ready and self.aapl_red_streak >= 3:
            allocation = 20_000.0
            if float(self.portfolio.cash) >= allocation:
                quantity = int(allocation // aapl_close)
                if quantity > 0:
                    self.market_order(
                        self.symbols["AAPL"], quantity, tag="Strategy B buy"
                    )
                    self.strategy_b_shares = quantity

        self.previous_spy_close = spy_close
        self.previous_spy_sma = (
            float(self.spy_sma.current.value) if self.spy_sma.is_ready else None
        )
        for ticker, bar in bars.items():
            self.previous_closes[ticker] = float(bar.close)

