class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent, close-of-day strategies with privately tracked lots."""

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        # The strategy description does not specify an SMA length.  Use the
        # conventional 20-trading-day simple moving average.
        self.sma_period = 20
        self.spy_closes = deque(maxlen=self.sma_period)
        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Market-state quantities continue to update even when another
        # subscribed ticker is absent and trading must be skipped.
        spy_today_close = None
        spy_today_sma = None
        if "SPY" in bars:
            spy_today_close = float(bars["SPY"].Close)
            self.spy_closes.append(spy_today_close)
            if len(self.spy_closes) == self.sma_period:
                spy_today_sma = sum(self.spy_closes) / self.sma_period

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].Close)
            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close
            self.aapl_rsi.Update(bars["AAPL"].EndTime, aapl_close)

        complete_day = len(bars) == len(self.symbols)
        if complete_day:
            self._evaluate_spy(spy_today_close, spy_today_sma)
            self._evaluate_aapl(float(bars["AAPL"].Close))

        # These values describe adjacent SPY trading bars, including bars on
        # days when the all-symbol data requirement prevented evaluation.
        if "SPY" in bars:
            self.previous_spy_close = spy_today_close
            self.previous_spy_sma = spy_today_sma

    def _evaluate_spy(self, close, sma):
        if sma is None or self.previous_spy_sma is None:
            return

        crosses_above = (
            self.previous_spy_close <= self.previous_spy_sma and close > sma
        )
        crosses_below = (
            self.previous_spy_close >= self.previous_spy_sma and close < sma
        )

        # Sells are evaluated before buys, and each reason is gated by this
        # strategy's private lot state.
        if self.spy_lot > 0:
            if crosses_below:
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
        elif crosses_above:
            quantity = int((0.40 * float(self.Portfolio.TotalPortfolioValue)) / close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

    def _evaluate_aapl(self, close):
        if self.aapl_lot > 0:
            if self.aapl_rsi.IsReady and float(self.aapl_rsi.Current.Value) > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
        elif self.aapl_red_streak >= 3:
            allocation = 20_000.0
            if float(self.Portfolio.Cash) >= allocation:
                quantity = int(allocation // close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

