class IndependentSmaAndRsiStrategies(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0
        self.pending_orders = {}

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Indicators and market-state values continue to advance whenever their
        # own ticker has a bar, even if another ticker is absent today.
        if "SPY" in bars:
            spy_bar = bars["SPY"]
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        all_bars_present = len(bars) == len(self.symbols)
        indicators_ready = self.spy_sma.IsReady and self.aapl_rsi.IsReady
        spy_cross_history_ready = self.previous_spy_sma is not None

        if all_bars_present and indicators_ready and spy_cross_history_ready:
            spy_close = bars["SPY"].Close
            spy_sma = self.spy_sma.Current.Value

            spy_crossed_below = (
                self.previous_spy_close >= self.previous_spy_sma
                and spy_close < spy_sma
            )

            # Evaluate every sell before either independent strategy may buy.
            if (
                self.strategy_a_quantity > 0
                and not self._has_pending_order("A")
                and spy_crossed_below
            ):
                self._submit_order(
                    self.symbols["SPY"],
                    -self.strategy_a_quantity,
                    "A",
                    "Strategy A liquidation",
                )

            if (
                self.strategy_b_quantity > 0
                and not self._has_pending_order("B")
                and self.aapl_rsi.Current.Value > 60
            ):
                self._submit_order(
                    self.symbols["AAPL"],
                    -self.strategy_b_quantity,
                    "B",
                    "Strategy B liquidation",
                )

            spy_crossed_above = (
                self.previous_spy_close <= self.previous_spy_sma
                and spy_close > spy_sma
            )

            if (
                self.strategy_a_quantity == 0
                and not self._has_pending_order("A")
                and spy_crossed_above
            ):
                quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
                if quantity > 0:
                    self._submit_order(
                        self.symbols["SPY"], quantity, "A", "Strategy A entry"
                    )

            if (
                self.strategy_b_quantity == 0
                and not self._has_pending_order("B")
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20_000
            ):
                quantity = int(20_000 // bars["AAPL"].Close)
                if quantity > 0:
                    self._submit_order(
                        self.symbols["AAPL"], quantity, "B", "Strategy B entry"
                    )

        if "SPY" in bars:
            self.previous_spy_close = bars["SPY"].Close
            self.previous_spy_sma = (
                self.spy_sma.Current.Value if self.spy_sma.IsReady else None
            )
        if "AAPL" in bars:
            self.previous_aapl_close = bars["AAPL"].Close

    def _submit_order(self, symbol, quantity, strategy, tag):
        ticket = self.MarketOrder(symbol, quantity, False, tag)
        self.pending_orders[ticket.OrderId] = strategy

    def _has_pending_order(self, strategy):
        return strategy in self.pending_orders.values()

    def OnOrderEvent(self, order_event):
        strategy = self.pending_orders.get(order_event.OrderId)
        if strategy is None:
            return

        if order_event.FillQuantity != 0:
            if strategy == "A":
                self.strategy_a_quantity += order_event.FillQuantity
                self.strategy_a_quantity = max(0, self.strategy_a_quantity)
            else:
                self.strategy_b_quantity += order_event.FillQuantity
                self.strategy_b_quantity = max(0, self.strategy_b_quantity)

        if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            del self.pending_orders[order_event.OrderId]

