            return

        self._evaluate_strategy_a(Decimal(str(bars["SPY"].close)))
        self._evaluate_strategy_b(Decimal(str(bars["AAPL"].close)))

    def _evaluate_strategy_a(self, close):
        if len(self.spy_closes) < self.SMA_PERIOD + 1:
            return

        closes = list(self.spy_closes)
        yesterday_sma = sum(closes[:-1]) / Decimal(self.SMA_PERIOD)
        today_sma = sum(closes[1:]) / Decimal(self.SMA_PERIOD)
        yesterday_close = closes[-2]

        crosses_below = yesterday_close >= yesterday_sma and close < today_sma
        crosses_above = yesterday_close <= yesterday_sma and close > today_sma

        if self.strategy_a_shares > 0 and crosses_below:
            self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_a_shares == 0 and crosses_above:
